claim_compilation_result.query:
(
    df.filter(
        prompt("The customer support dialog {dialog} contains a customer complaint")
    )
    .map(
        prompt(
            "Identify whether the customer support dialog {dialog} is a complaint regarding flight delays",
            bool
        ).alias("is_flight_delay_complaint")
    )
    .aggregate(
        [proportion(col("is_flight_delay_complaint")).alias("flight_delay_prop")],
        group_by=[col("company_id")]
    )
    .aggregate(
        [count_if(col("flight_delay_prop") > 0.15).alias("num_companies")]
    )
    .check(col("num_companies").eq(4))
)
